namespace Ta3lom.Store.Application.Interfaces;

/// File storage: `LocalFileStorage` under `Store:Files:Root` with `public/` (served at `/files/public`) and `private/`
/// (never served directly). Keys are relative paths generated by the server.
public interface IFileStorage
{
    Task SaveAsync(string storageKey, bool isPublic, Stream content, CancellationToken ct = default);

    Task<Stream?> OpenReadAsync(string storageKey, bool isPublic, CancellationToken ct = default);

    Task DeleteAsync(string storageKey, bool isPublic, CancellationToken ct = default);
}

/// Public URLs of stored files: `{Store:Files:PublicBaseUrl}/{storage_key}`.
public interface IFileUrls
{
    string Public(string storageKey);
}

/// Image upload processing: decode, refuse more than `maxPixels` before decoding the pixels, re-encode to WebP (drops
/// EXIF and other metadata) with the longest edge at most `maxEdge`.
public interface IImageProcessor
{
    ImageProcessResult ToWebp(ReadOnlySpan<byte> input, int maxEdge, long maxPixels);
}

public enum ImageProcessStatus
{
    Ok,
    NotAnImage,
    TooManyPixels,
}

public sealed record ImageProcessResult(ImageProcessStatus Status, ProcessedImage? Image);

public sealed record ProcessedImage(byte[] Bytes, int Width, int Height);
